 const manifest={sessionId:'s',environmentImageDigest:image,dockerContext:'desktop-linux',networkPolicy:'none',command:['python','analysis.py'],resources:{cpus:1,memoryMb:1024,pids:64,timeoutSeconds:120,workMb:128,outputBytes:33554432,logBytes:2097152},dataArtifacts:[{id:'input'}],inputSnapshot:{files:[{path:'analysis.py'}]}};
 assert.doesNotThrow(()=>validateDevelopment(manifest,scope));for(const patch of [{sessionId:'other'},{environmentImageDigest:'other'},{dockerContext:'remote'},{networkPolicy:'default'},{dataArtifacts:[{id:'hidden'}]},{inputSnapshot:{files:[{path:'target_study/answer.py'}]}},{resources:{...manifest.resources,cpus:99}}])assert.throws(()=>validateDevelopment({...manifest,...patch},scope),{code:'DEVELOPMENT_SCOPE_DENIED'});
