 const second='GPU-00000000-0000-0000-0000-000000000002';assert.deepEqual(parseArgs(args).gpuDevices,[]);assert.throws(()=>parseArgs([...args,'--gpu-device',uuid]),{code:'GPU_OPTIONS_INVALID'});assert.throws(()=>parseArgs([...args,'--gpu-device','all','--gpu-image','cuda@sha256:'+'b'.repeat(64)]),{code:'GPU_OPTIONS_INVALID'});assert.deepEqual(parseArgs([...args,'--gpu-device',second,'--gpu-device',uuid,'--gpu-device',uuid,'--gpu-image','cuda@sha256:'+'b'.repeat(64)]).gpuDevices,[uuid,second]);
