test('fixed successful snapshot exports generated source trees including extensionless scripts, never inputs or mutable session files',async t=>{
 const {exportSnapshotSources,sha256}=await harness(),root=fixture(t),destination=fixture(t),script=Buffer.from('#!/bin/sh\npython code/analyze.py\n'),analysis=Buffer.from('print("measured")\n');mkdirSync(join(root,'code'));writeFileSync(join(root,'run-analysis'),script);writeFileSync(join(root,'code','analyze.py'),analysis);writeFileSync(join(root,'INSTRUCTIONS.md'),'original prompt');
 const files=[{digest:sha256(Buffer.from('x,y\n1,2\n')),mode:'100644',path:'data/observations.csv',size:8},{digest:sha256(Buffer.from('original prompt')),mode:'100644',path:'INSTRUCTIONS.md',size:15},{digest:sha256(script),mode:'100755',path:'run-analysis',size:script.length},{digest:sha256(analysis),mode:'100644',path:'code/analyze.py',size:analysis.length}],sourceDigest=sha256(JSON.stringify(files)),producer={kind:'development',id:'actual-job',state:'succeeded',integrity:'complete',exitCode:0,sourceDigest};
 writeFileSync(join(root,'unfrozen-late-script'),'not in the executed descriptor');
 const copied=Buffer.from('x,y\n1,2\n');writeFileSync(join(root,'copied-input.csv'),copied);files.push({digest:sha256(copied),mode:'100644',path:'copied-input.csv',size:copied.length});const actualDigest=sha256(JSON.stringify(files)),actualProducer={...producer,sourceDigest:actualDigest};
 const records=exportSnapshotSources({workspace:destination,snapshot:{root,path:root,files},producer:actualProducer,sourceDigest:actualDigest,originalInputs:[{path:'INSTRUCTIONS.md'},{path:'data/observations.csv',sha256:sha256(copied)}]});assert.deepEqual(records.map(r=>r.sourcePath),['run-analysis','code/analyze.py']);assert.deepEqual(readFileSync(join(destination,'code','development-actual-job','run-analysis')),script);assert.equal(existsSync(join(destination,'code','development-actual-job','unfrozen-late-script')),false);assert.equal(records[0].sourceDigest,actualDigest);assert.equal(records[0].producer.id,'actual-job');assert.equal(records[0].sourceFileMode,'100755');
 writeFileSync(join(root,'run-analysis'),'changed after freeze');assert.throws(()=>exportSnapshotSources({workspace:destination,snapshot:{root,path:root,files},producer:actualProducer,sourceDigest:actualDigest,originalInputs:[]}),{code:'SNAPSHOT_FILE_MISMATCH'});
});
