test('dead-host elapsed history uses only complete durable observations and labels unobserved gaps',async()=>{
 const {deadHostObservation,startRecoveryWindow,sha256}=await harness(),evaluation={status:'running',startedAt:'2026-10-25T08:00:00Z'},now=Date.parse('2026-10-25T09:00:00Z'),progress=Buffer.from('{"at":"2026-10-25T08:10:00Z","type":"heartbeat"}\n{"at":"2026-10-25T08:50:00Z"'),observation=deadHostObservation(evaluation,progress,now),window=startRecoveryWindow(evaluation,{id:'dead-host',now,timeoutSeconds:1800,observation});
 assert.equal(window.priorObservedElapsedMs,600000);assert.equal(window.gapObservedMs,3000000);assert.equal(window.lastObservedAt,'2026-10-25T08:10:00.000Z');assert.equal(window.windowSeconds,1800);assert.equal(window.progressEvidence.sha256,sha256(progress));assert.equal(window.progressEvidence.type,'heartbeat');assert.match(window.measurement,/not active runtime/);assert.equal(evaluation.endedAt,undefined);
 for(const text of ['', '{"at":"2026-10-25T08:10:00Z","type":"heartbeat"}', '{"at":"2026-10-25T07:59:59Z","type":"heartbeat"}\n', '{"at":"2026-10-25T09:00:01Z","type":"heartbeat"}\n'])assert.throws(()=>deadHostObservation(evaluation,Buffer.from(text),now),{code:'RESUME_TIME_UNPROVEN'});
 assert.throws(()=>deadHostObservation({...evaluation,totalElapsedMs:1},progress,now),{code:'RESUME_TIME_UNPROVEN'});
});
