 writeFileSync(join(s.app.store.paths.physical(session.workspace),'main.py'),'assert True');const actor={type:'agent',role:'coordinator',projectId:s.project.id,sessionId:session.id,generation:1,messageId:first.id,researchModelDigest:s.app.researchAutomation.modelIdentity(session),permission:s.app.sessionPermissions.capture(session.id)},prepared=s.app.development.prepare(actor,s.project.id,session.id,{command:['python','main.py'],environmentImageDigest:'cpu@sha256:'+'a'.repeat(64)}),approval=s.app.store.get('approval',prepared.grantId);s.app.approvals.decide(USER,approval.id,approval.version,true);const task=s.app.store.get('development-task',prepared.id);s.app.store.update('development-task',task.id,task.version,{state:'submitted',jobId:'saved-job'});const wakeup=s.app.store.list('wakeup')[0];assert.equal(wakeup.state,'pending');
